 1	/**
 2	 * Component that tracks an entity's field and location.
 3	 */
 4	public final class SpatialComponent implements EntityComponent
 5	{
 6	    private Field field;
 7	    private Location location;
 8	
 9	    public SpatialComponent(Field field, Location location)
10	    {
11	        this.field = field;
12	        this.location = location;
13	    }
14	
15	    public Field getField()
16	    {
17	        return field;
18	    }
19	
20	    public Location getLocation()
21	    {
22	        return location;
23	    }
24	
25	    public void place(Object occupant)
26	    {
27	        ensureBound();
28	        field.place(occupant, location);
29	    }
30	
31	    public void move(Object occupant, Location newLocation)
32	    {
33	        ensureBound();
34	        if(location != null) {
35	            field.clear(location);
36	        }
37	        location = newLocation;
38	        field.place(occupant, newLocation);
39	    }
40	
41	    public void clear()
42	    {
43	        if(field != null && location != null) {
44	            field.clear(location);
45	        }
46	        field = null;
47	        location = null;
48	    }
49	
50	    private void ensureBound()
51	    {
52	        if(field == null) {
53	            throw new IllegalStateException("Spatial component is no longer bound to a field.");
54	        }
55	    }
56	}
